# stale text + suspicious chars
pats=['anuidade','será restabelecida antes do fechamento','resolvido no Fechamento','solvido','Exposensão','[\\u3000-\\u9fff]','[a-z]{3,}ção [a-z]']
for f in glob.glob('*.md')+['achados.json']:
    t=open(f).read()
    for p in pats:
        for m in re.finditer(p,t):
            print('HIT',f,p,repr(t[max(0,m.start()-30):m.end()+30]))
print('done')
