cd /work/workspace/deliverable && python3 - <<'EOF'
import json,re,glob
d=json.load(open('achados.json'))
ok={'anuencia','preco','indenizacao','prazo','nenhum'}
assert all(set(x)=={'achado','onde','por_que_importa','efeito','solucao'} and x['efeito'] in ok for x in d)
print('JSON OK,',len(d),'items')
idx=open('../library/INDEX.md').read()
white={w.strip('`') for w in re.findall(r'`([a-z0-9_]+\.md)`',idx)}
print('whitelist:',sorted(white))
bad=[]
for f in glob.glob('*.md')+['achados.json']:
    t=open(f).read()
    for m in set(re.findall(r'library/([A-Za-z0-9_./-]+\.md)',t)):
        if m=='INDEX.md': continue
        if m not in white: bad.append((f,m))
print('citation misses:',bad if bad else 'none')
# stray latin-only English words that crept in + non-ascii oddities
sus=re.compile(r'\b(mechanism|condition precedent|não condition|limbos|no/n)\b')
cjk=re.compile(r'[\u3000-\u9fff\uff00-\uffef]')
for f in glob.glob('*.md')+['achados.json']:
    t=open(f).read()
    for pat,name in [(sus,'en-word'),(cjk,'cjk')]:
        for m in pat.finditer(t):
            print('HIT',f,name,repr(t[max(0,m.start()-40):m.end()+40]))
print('done')
EOF

